// CabinetOS Game events: your Discord status shows the game you are playing.
// Your Discord application's Client ID, from its OAuth2 page.
const APP_ID = "PASTE-THE-CLIENT-ID";
// Whose games: the console account's name exactly as the console shows it.
const PERSON = "PASTE-THE-NAME";
// Stop showing a game after this many hours with no word from the console,
// since a power cut sends no "game ended".
const MAX_HOURS = 8;

const s = $getWorkflowStaticData('global');
const now = Date.now();
// Discord drops a session after 20 minutes; after 19, start a new one.
const live = Boolean(s.token && s.sentAt && now - s.sentAt < 19 * 60 * 1000);
// The console's message, or nothing when the 15-minute clock started this run.
const body = $input.first().json.body;

function end() {
  const token = live ? s.token : null;
  s.playing = null;
  s.token = null;
  s.sentAt = null;
  return token ? [{ json: { action: 'end', token } }] : [];
}

if (body) {
  // The console sends a test when it starts or joins a network: nothing is
  // playing then.
  if (body.event === 'test') return end();
  if (body.person !== PERSON) return [];
  if (body.event === 'game_started') {
    s.playing = { game: body.game, system: body.system, start: Date.parse(body.time) || now, paused: false, heard: now };
  } else if (body.event === 'game_paused' || body.event === 'game_resumed') {
    if (!s.playing) return [];
    s.playing.paused = body.event === 'game_paused';
    s.playing.heard = now;
  } else if (body.event === 'game_ended') {
    return end();
  } else {
    return [];
  }
} else {
  if (!s.playing) return [];
  if (now - s.playing.heard > MAX_HOURS * 3600 * 1000) return end();
}

const p = s.playing;
const cut = (t) => String(t ?? '').slice(0, 128);
const activity = { type: 0, application_id: APP_ID, name: cut(p.game), details: cut(p.system), platform: 'desktop' };
if (p.paused) activity.state = 'Paused';
else activity.timestamps = { start: p.start };
const request = { activities: [activity] };
if (live) request.token = s.token;
return [{ json: { action: 'set', request } }];

// Keep the session Discord gave back, so the next update goes to the same one.
const s = $getWorkflowStaticData('global');
const token = $input.first().json.token;
if (token && s.playing) {
  s.token = token;
  s.sentAt = Date.now();
}
return $input.all();

// Discord turned the update down, often because the session had run out:
// the next one starts a new session.
const s = $getWorkflowStaticData('global');
s.token = null;
s.sentAt = null;
return $input.all();
